const CACHE='nextplay-v6';const CORE=['./','./index.html','./style.css','./app.mjs','./engine.mjs','./recommendation-api.mjs','./extra-games.mjs','./catalog-expansion.mjs','./daily.mjs','./ratings.mjs','./critic-sources.mjs','./catalog-data.mjs','./pager.mjs','./bulk-catalog.json','./scoring.mjs','./rankings.mjs','./importer.mjs','./assets/cover-pending.svg','./steam-data.json','./icon.svg','./icons.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest','./assets/hls.min.js'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(CORE))));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r}).catch(()=>caches.match(e.request).then(r=>r||new Response('Нет соединения. Этот ресурс ещё не сохранён.',{status:503}))));});
